{
 "title": "Potential Domain Reconnaissance Using Net or Query Commands",
 "description": "Detects execution of net user, net group, or query commands which are commonly used for domain account enumeration as seen in Atomic Red Team tests T1087.002.",
 "tags": [
  "attack.t1087.002",
  "attack.discovery"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "selection_net_user_domain",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "net user"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "/domain"
     ]
    }
   ]
  },
  {
   "name": "selection_net_group_domain",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "net group"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "/domain"
     ]
    }
   ]
  },
  {
   "name": "selection_query_logged_on_users",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "exact",
     "values": [
      "query"
     ]
    }
   ]
  }
 ],
 "condition": "(selection_net_user_domain or selection_net_group_domain or selection_query_logged_on_users)",
 "falsepositives": [
  "Legitimate administrative use of net or query commands for system management."
 ],
 "level": "medium"
}
